style.css:
@-moz-document domain("google.com") {
/* 1. Global Custom Font & Main Layout Background */
    html, body, #gsr, #viewport, #searchform, .cnt, 
    input, button, span, a, div, h3, cite {
        font-family: 'Segoe UI', Roboto, Helvetica, Arial, system-ui, sans-serif !important;
        letter-spacing: -0.01em !important;
    }

    html, body, #gsr, #viewport, #searchform, .cnt {
        background-color: #e8f5e9 !important;
        color: #1b5e20 !important;
    }

    /* 2. Strict Typography Overrides (Dark Green Font Colors Maintained) */
    h3, .LC20lb, [class*="title"] h3, a h3 {
        color: #0c3813 !important; /* Deep forest green links */
        font-weight: 500 !important;
    }
    
    h3:hover, a:hover h3 {
        color: #2e7d32 !important;
        text-decoration: underline !important;
    }

    /* Text Snippets under search results */
    span[class*="st"], div[class*="st"], .VwiC3b, .MUxGbd, .hgKElc {
        color: #2d4a30 !important; /* Cohesive readable dark charcoal green */
    }

    /* Breadcrumbs and web links */
    cite, cite *, .tjvXA, .byrV5b {
        color: #388e3c !important;
    }

    /* Visited Search Items */
    a:visited h3, [class*="visited"] h3 {
        color: #4e7051 !important;
    }

    /* 3. Search Field Styling */
    form[action="/search"] .RNNXgb, .SDkbee, input[type="text"] {
        background-color: #ffffff !important;
        border: 2px solid #a5d6a7 !important;
        color: #1b5e20 !important;
    }

    /* 4. Complete Logo Overhaul */
    img[src*="logo"], 
    img[alt="Google"], 
    .lnXpfc, 
    .logo img, 
    #logo img,
    div[style*="logo"] {
        filter: brightness(0) saturate(100%) invert(27%) sepia(51%) saturate(913%) hue-rotate(81deg) brightness(91%) contrast(92%) !important;
    }

    /* Direct path structural support for modern vector graphic implementations */
    svg path, svg g path {
        fill: #1b5e20 !important;
    }
}
